import type { Metadata } from "next";
import Link from "next/link";
import { Suspense } from "react";
import { Heart } from "lucide-react";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { ProductCard } from "@/components/store/ProductCard";
import { Reveal } from "@/components/store/Reveal";

export const metadata: Metadata = { title: "My Wishlist", robots: { index: false } };

async function WishlistContent() {
  const user = await requireUser("/account/wishlist");
  const items = await db.wishlistItem.findMany({
    where: { userId: user.id, product: { isActive: true } },
    orderBy: { createdAt: "desc" },
    include: {
      product: {
        select: {
          id: true, name: true, slug: true, brand: true, material: true, price: true, mrp: true, stock: true, ratingAvg: true, ratingCount: true,
          emiEligible: true, engravingAvailable: true, isFeatured: true,
          category: { select: { name: true, slug: true } },
          images: { select: { url: true, alt: true }, orderBy: { sortOrder: "asc" }, take: 2 },
        },
      },
    },
  });

  if (!items.length) {
    return (
      <div className="animate-scale-in card flex flex-col items-center p-12 text-center">
        <Heart className="animate-float h-12 w-12 text-maroon/70" aria-hidden />
        <p className="mt-4 font-display text-2xl font-semibold">Your wishlist is empty</p>
        <p className="mt-1 text-sm text-muted">Tap the heart on any product to save it for later.</p>
        <Link href="/search" className="btn-primary press mt-5">Discover products</Link>
      </div>
    );
  }
  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-4 lg:grid-cols-4">
      {items.map((w, i) => (
        <Reveal key={w.id} delay={(i % 4) * 70}>
          <ProductCard product={w.product} morph />
        </Reveal>
      ))}
    </div>
  );
}

export default function WishlistPage() {
  return (
    <div className="container-x py-6">
      <div className="mb-5 flex items-center justify-between">
        <h1 className="font-display text-3xl font-semibold">My Wishlist</h1>
        <Link href="/account" className="text-sm text-maroon hover:underline">← Account</Link>
      </div>
      <Suspense fallback={<div className="grid grid-cols-2 gap-4 sm:grid-cols-4">{[0, 1, 2, 3].map((i) => <div key={i} className="skeleton aspect-[3/4] rounded-xl" />)}</div>}>
        <WishlistContent />
      </Suspense>
    </div>
  );
}
